## Java Code

```java
/**
 *  Utility class that contains the BST‑validation method.
 *  The Node class is assumed to be defined elsewhere, e.g.:
 *
 *  class Node {
 *      int data;
 *      Node left, right;
 *      Node(int d) { data = d; }
 *  }
 */
public class BSTValidator {

    /**
     * Public entry point – call this method with the root of the tree.
     *
     * @param root the root node of the binary tree
     * @return true iff the tree obeys the binary‑search‑tree ordering rules
     */
    public static boolean isBST(Node root) {
        // Using Long.MIN_VALUE / Long.MAX_VALUE prevents overflow when the tree
        // contains Integer.MIN_VALUE or Integer.MAX_VALUE.
        return isBSTRec(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    /**
     * Recursive helper that carries the allowed value interval.
     *
     * @param node   current node being inspected
     * @param lower  exclusive lower bound for node.data
     * @param upper  exclusive upper bound for node.data
     * @return true if the subtree rooted at {@code node} satisfies the BST property
     */
    private static boolean isBSTRec(Node node, long lower, long upper) {
        // An empty subtree is always a valid BST.
        if (node == null) {
            return true;
        }

        // The current node must lie strictly between lower and upper.
        if (node.data <= lower || node.data >= upper) {
            return false;
        }

        // Recursively validate left and right sub‑trees with updated bounds.
        return isBSTRec(node.left, lower, node.data)   // left < node.data
            && isBSTRec(node.right, node.data, upper); // right > node.data
    }

    /* ------------------------------------------------------------------ */
    /*  Optional: an iterative version that uses an explicit stack.      */
    /*  Useful if you want to avoid recursion depth limits on very deep   */
    /*  trees.                                                            */
    /* ------------------------------------------------------------------ */
    public static boolean isBSTIterative(Node root) {
        if (root == null) return true;

        // Stack entries keep a node together with its allowed interval.
        class StackEntry {
            Node node;
            long lower, upper;
            StackEntry(Node n, long lo, long hi) { node = n; lower = lo; upper = hi; }
        }

        java.util.Deque<StackEntry> stack = new java.util.ArrayDeque<>();
        stack.push(new StackEntry(root, Long.MIN_VALUE, Long.MAX_VALUE));

        while (!stack.isEmpty()) {
            StackEntry e = stack.pop();
            Node cur = e.node;
            long lo = e.lower, hi = e.upper;

            if (cur == null) continue;

            if (cur.data <= lo || cur.data >= hi) {
                return false;
            }

            // Push right child first so that left child is processed first
            // (mirrors the recursive order, but order does not matter for correctness).
            stack.push(new StackEntry(cur.right, cur.data, hi));
            stack.push(new StackEntry(cur.left, lo, cur.data));
        }

        return true;
    }

    /* ------------------------------------------------------------------ */
    /*  Demo / quick test                                                  */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) {
        // Build a small example tree:
        //        8
        //      /   \
        //     3    10
        //    / \     \
        //   1   6     14
        //      / \   /
        //     4   7 13
        Node root = new Node(8);
        root.left = new Node(3);
        root.right = new Node(10);
        root.left.left = new Node(1);
        root.left.right = new Node(6);
        root.left.right.left = new Node(4);
        root.left.right.right = new Node(7);
        root.right.right = new Node(14);
        root.right.right.left = new Node(13);

        System.out.println("Recursive check: " + isBST(root));        // true
        System.out.println("Iterative check: " + isBSTIterative(root)); // true

        // Break the BST property: make left child larger than its parent
        root.left.right.data = 9;   // 9 > 8 violates the rule
        System.out.println("\nAfter corrupting the tree:");
        System.out.println("Recursive check: " + isBST(root));        // false
        System.out.println("Iterative check: " + isBSTIterative(root)); // false
    }
}
```

